namespace RonSijm.FluidHumidifier.Factories.SageMaker;

public class WorkforceFactory(string resourceName = null, Action<Humidifier.SageMaker.Workforce> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.Workforce>(resourceName)
{

    internal InnerWorkforceOidcConfigFactory OidcConfigFactory { get; set; }

    internal InnerWorkforceCognitoConfigFactory CognitoConfigFactory { get; set; }

    internal InnerWorkforceWorkforceVpcConfigRequestFactory WorkforceVpcConfigFactory { get; set; }

    internal InnerWorkforceSourceIpConfigFactory SourceIpConfigFactory { get; set; }

    protected override Humidifier.SageMaker.Workforce Create()
    {
        var workforceResult = CreateWorkforce();
        factoryAction?.Invoke(workforceResult);

        return workforceResult;
    }

    private Humidifier.SageMaker.Workforce CreateWorkforce()
    {
        var workforceResult = new Humidifier.SageMaker.Workforce
        {
            GivenName = InputResourceName,
        };

        return workforceResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.Workforce result)
    {
        base.CreateChildren(result);

        result.OidcConfig ??= OidcConfigFactory?.Build();
        result.CognitoConfig ??= CognitoConfigFactory?.Build();
        result.WorkforceVpcConfig ??= WorkforceVpcConfigFactory?.Build();
        result.SourceIpConfig ??= SourceIpConfigFactory?.Build();
    }

} // End Of Class

